"""One video frame per real capture, without held/upconverted/interpolated images."""
import bpy,json,sys,hashlib
from pathlib import Path
folder=Path(sys.argv[sys.argv.index('--')+1]).resolve();d=json.loads((folder/'capture.json').read_text());assert d['status']=='actual_owned_window_reads';frames=d['frames'];dest=folder/'actual_gameplay_review.mp4';assert not dest.exists();fps=30
bpy.ops.wm.read_factory_settings(use_empty=True);s=bpy.context.scene;s.view_settings.view_transform='Standard';s.view_settings.look='None';s.view_settings.exposure=0;s.view_settings.gamma=1;s.render.use_stamp=False;s.render.resolution_x=d['width'];s.render.resolution_y=d['height'];s.render.resolution_percentage=100;s.render.fps=fps;s.frame_start=1;s.frame_end=len(frames);seq=s.sequence_editor_create();strip=seq.strips.new_image('MotionDiagnostic',str(folder/'frames'/frames[0]['png']),channel=1,frame_start=1)
for row in frames[1:]:strip.elements.append(row['png'])
strip.frame_final_duration=len(frames);s.render.use_sequencer=True;s.render.image_settings.file_format='FFMPEG';s.render.ffmpeg.format='MPEG4';s.render.ffmpeg.codec='H264';s.render.filepath=str(dest);bpy.ops.render.render(animation=True);assert dest.stat().st_size>0
report={'sha256':hashlib.sha256(dest.read_bytes()).hexdigest(),'capture_sha256':hashlib.sha256((folder/'capture.json').read_bytes()).hexdigest(),'encoded_fps':fps,'encoded_frames':len(frames),'encoded_duration_seconds':len(frames)/fps,'actual_capture_duration_seconds':d['duration_seconds'],'actual_capture_fps':d['achieved_capture_fps'],'missed_capture_slots':d['estimated_missed_30hz_slots'],'interpolation':False,'held_frame_upconversion':False,'mapping':'Exactly one output frame per actual PNG in capture order. Constant30fps encoding may shorten wall-clock duration if capture missed target; use original timestamps and local executable to judge timing. No audio.'};(folder/'video-provenance.json').write_text(json.dumps(report,indent=2)+'\n')
